svg.script:
(function () {
  var svg = document.currentScript.ownerSVGElement;
  function jump(event) {
    if (event.type === "keydown" && event.key !== "Enter" && event.key !== " ") { return; }
    svg.setCurrentTime(Number(event.currentTarget.getAttribute("data-time")));
    svg.unpauseAnimations();
  }
  svg.querySelectorAll(".step-hit").forEach(function (hit) {
    hit.addEventListener("click", jump);
    hit.addEventListener("keydown", jump);
  });
})();
